import { Component } from 'react';
import { Form, Button, Container, Row, Col, Image } from 'react-bootstrap';
import PortfolioService from '../../../services/portfolio.service';
import UploadService from '../../../services/upload.service';
import './NewImageForm.css';

class NewImageForm extends Component {
	constructor() {
		super();

		this.state = {
			img_url: '',
			tags: '',
			loading: false,
		};

		this.portfolioService = new PortfolioService();
		this.uploadService = new UploadService();
	}

	handleInputChange = e => {
		// let { name, value } = e.target;
		// this.setState({ [name]: value });

		// while img is taken as file, we need only to check tags input
		this.setState({ tags: e.target.value });
	};

	handleFileUpload = e => {
		this.setState({ loading: true });

		const uploadData = new FormData();
		uploadData.append('imageData', e.target.files[0]);

		this.uploadService
			.uploadImage(uploadData)
			.then(response => {
				this.setState({
					loading: false,
					img_url: response.data.cloudinary_url,
				});
			})
			.catch(err => this.props.setAlert(err.response.data.message));
	};

	handleFormSubmit = e => {
		e.preventDefault();

		this.portfolioService
			.saveImage({ img_url: this.state.img_url, tags: this.state.tags.split(/,\s*/) })
			.then(() => {
				this.props.refreshList();
				this.props.closeModal();
			})
			.catch(err => this.props.setAlert(err.response.data.message));
	};

	render = () => (
		<Container>
			<Form onSubmit={this.handleFormSubmit}>
				{/* <Form.Group controlId="img_url">
					<Form.Label>Image url</Form.Label>
					<Form.Control type="text" value={this.state.img_url} onChange={this.handleInputChange} name="img_url" />
				</Form.Group> */}

				<Form.Group controlId="img_url" className="mb-3">
					<Form.Label>Image file</Form.Label>
					<br />
					<Form.Control type="file" onChange={this.handleFileUpload} disabled={this.state.loading} />
					<Container>
						<Row className="justify-content-center">
							<Col xs={8} sm={6} md={4}>
								{this.state.img_url && !this.state.loading && (
									<Image src={this.state.img_url} className="upload-image-prev"></Image>
								)}
							</Col>
						</Row>
					</Container>
				</Form.Group>

				<br />

				<Form.Group controlId="tags">
					<Form.Label>Tags (comma separated)</Form.Label>
					<Form.Control
						type="textarea"
						value={this.state.tags}
						onChange={this.handleInputChange}
						name="tags"
						placeholder="First, second, third..."
					/>
				</Form.Group>

				<Button style={{ marginTop: '20px', width: '100%' }} variant="dark" type="submit" disabled={this.state.loading}>
					{this.state.loading ? 'Loading image...' : 'Add image'}
				</Button>
			</Form>
		</Container>
	);
}

export default NewImageForm;
