import { Component } from 'react';
import { Button, Col, Container, Form, Row } from 'react-bootstrap';
import { Link } from 'react-router-dom';
import AuthService from '../../../services/auth.service';

class Signup extends Component {
	constructor() {
		super();

		this.state = {
			username: '',
			password: '',
			role: '',
		};

		this.authService = new AuthService();
	}

	handleInputChange = e => {
		const { name, value } = e.target;

		this.setState({ [name]: value });
	};

	handleFormSubmit = e => {
		e.preventDefault();

		const { username, password, role } = this.state;

		this.authService
			.signup(username, password, role)
			.then(response => {
				this.props.storeUser(response.data);
				response.data.role === 'ARTIST' ? this.props.history.push('/my-portfolio') : this.props.history.push('/');
			})
			.catch(err => this.props.setAlert(err.response.data.message));
	};

	render = () => (
		<Container>
			<Row className="justify-content-center">
				<Col xs={8}>
					<Form onSubmit={this.handleFormSubmit}>
						<Form.Group className="mb-3" controlId="username">
							<Form.Label>Username</Form.Label>
							<Form.Control
								type="text"
								value={this.state.username}
								onChange={this.handleInputChange}
								name="username"
								required
							/>
						</Form.Group>

						<Form.Group className="mb-3" controlId="password">
							<Form.Label>Password</Form.Label>
							<Form.Control
								type="password"
								value={this.state.password}
								onChange={this.handleInputChange}
								name="password"
								required
							/>
						</Form.Group>

						<Form.Group className="mb-3">
							<Form.Check
								inline
								type="radio"
								label="Artist"
								value="ARTIST"
								checked={this.state.role === 'ARTIST'}
								onChange={this.handleInputChange}
								name="role"
								required
							/>

							<Form.Check
								inline
								type="radio"
								label="Recruiter"
								value="RECRUITER"
								checked={this.state.role === 'RECRUITER'}
								onChange={this.handleInputChange}
								name="role"
							/>
						</Form.Group>

						<Button variant="dark" type="submit">
							Sign up
						</Button>
					</Form>

					<hr />

					<Link to="/">
						<Button variant="light">Go back</Button>
					</Link>
				</Col>
			</Row>
		</Container>
	);
}

export default Signup;
