import { Col } from 'react-bootstrap';
import './JobOfferItem.css';

const JobOfferItem = ({ id, brand, title, description, openDetails }) => {
	return (
		<Col sm={12} md={6} lg={4} xl={3}>
			<button className="job-offer-item" onClick={() => openDetails(id)}>
				<div className="content">
					<h3>{title}</h3>
					<p>
						For <span className="brand">{brand}</span>
					</p>
				</div>
			</button>
		</Col>
	);
};

export default JobOfferItem;
