import 'bootstrap/dist/css/bootstrap.min.css';
import './../resources/fontello-26f13a6e/css/fontello.css';
import './App.css';

import AuthService from '../services/auth.service';

import { Component } from 'react';

import NavigationBar from './layout/Navbar/NavigationBar';
import Routes from './routes';
import GlobalAlert from './shared/Alerts/GlobalAlert';
import Footer from './layout/Footer/Footer';

class App extends Component {
	constructor() {
		super();

		this.state = {
			loggedUser: undefined,

			alert: {
				message: '',
				show: false,
			},
		};

		this.authService = new AuthService();
	}

	storeUser = loggedUser => this.setState({ loggedUser });

	setAlert = message =>
		this.setState({
			alert: {
				message,
				show: true,
			},
		});

	closeAlert = () =>
		this.setState({
			alert: {
				message: '',
				show: false,
			},
		});

	fetchUser = () => {
		this.authService
			.isLoggedIn()
			.then(response => {
				this.storeUser(response.data);
			})
			.catch(err => {
				// this.setAlert(err.response.data.message);
				this.storeUser(null);
			});
	};

	componentDidMount = () => this.fetchUser();

	render = () => (
		<>
			<NavigationBar storeUser={this.storeUser} loggedUser={this.state.loggedUser} setAlert={this.setAlert} />

			<Routes storeUser={this.storeUser} loggedUser={this.state.loggedUser} setAlert={this.setAlert} />

			<GlobalAlert show={this.state.alert.show} message={this.state.alert.message} closeAlert={this.closeAlert} />

			<Footer />
		</>
	);
}

export default App;
