import { Component } from 'react';
import { Form, Button, Container } from 'react-bootstrap';
import UsersService from '../../../services/users.service';

class EditPortfolioForm extends Component {
	constructor() {
		super();

		this.state = {
			name: '',
			last_name: '',
			country: '',
			city: '',
			email: '',
			tel: '',
			about: '',
			experience: '',
			tags: '',
		};

		this.usersService = new UsersService();
	}

	componentDidMount = () => {
		this.setState({
			...this.props.loggedUser.portfolio,
			experience: this.props.loggedUser.portfolio.experience.join(', '),
			tags: this.props.loggedUser.portfolio.tags.join(', '),
		});
	};

	handleInputChange = e => {
		let { name, value } = e.target;
		this.setState({ [name]: value });
	};

	handleFormSubmit = e => {
		e.preventDefault();

		const experience = this.state.experience.split(/,\s*/);
		const tags = this.state.tags.split(/,\s*/);

		this.usersService
			.updatePortfolio({ ...this.state, experience, tags })
			.then(response => {
				this.props.closeModal();
				this.props.storeUser(response.data);
				this.props.refreshPortfolio(response.data);
				this.setState(response.data.portfolio);
			})
			.catch(err => this.props.setAlert(err.response.data.message));
	};

	render = () => (
		<Container>
			<Form onSubmit={this.handleFormSubmit}>
				<Form.Group controlId="name">
					<Form.Label>Name</Form.Label>
					<Form.Control type="text" value={this.state.name} onChange={this.handleInputChange} name="name" />
				</Form.Group>

				<Form.Group controlId="last_name">
					<Form.Label>Last name</Form.Label>
					<Form.Control type="text" value={this.state.last_name} onChange={this.handleInputChange} name="last_name" />
				</Form.Group>

				<hr />

				<Form.Group controlId="country">
					<Form.Label>Country</Form.Label>
					<Form.Control type="text" value={this.state.country} onChange={this.handleInputChange} name="country" />
				</Form.Group>

				<Form.Group controlId="city">
					<Form.Label>City</Form.Label>
					<Form.Control type="text" value={this.state.city} onChange={this.handleInputChange} name="city" />
				</Form.Group>

				<hr />

				<Form.Group controlId="email">
					<Form.Label>Email</Form.Label>
					<Form.Control type="text" value={this.state.email} onChange={this.handleInputChange} name="email" />
				</Form.Group>

				<Form.Group controlId="tel">
					<Form.Label>Tel.</Form.Label>
					<Form.Control type="text" value={this.state.tel} onChange={this.handleInputChange} name="tel" />
				</Form.Group>

				<hr />

				<Form.Group controlId="about">
					<Form.Label>About</Form.Label>
					<Form.Control type="textarea" value={this.state.about} onChange={this.handleInputChange} name="about" />
				</Form.Group>

				<Form.Group controlId="experience">
					<Form.Label>Experience (comma separated)</Form.Label>
					<Form.Control
						type="textarea"
						value={this.state.experience}
						onChange={this.handleInputChange}
						name="experience"
						placeholder="First, second, third..."
					/>
				</Form.Group>

				<hr />

				<Form.Group controlId="tags">
					<Form.Label>Tags (comma separated)</Form.Label>
					<Form.Control
						type="textarea"
						value={this.state.tags}
						onChange={this.handleInputChange}
						name="tags"
						placeholder="First, second, third..."
					/>
				</Form.Group>

				<Button style={{ marginTop: '20px', width: '100%' }} variant="dark" type="submit">
					Save portfolio
				</Button>
			</Form>
		</Container>
	);
}

export default EditPortfolioForm;
