import { Switch, Route, Redirect } from 'react-router-dom';
import HomePage from '../pages/Home/HomePage';
import Signup from '../pages/Signup/Signup';
import Login from '../pages/Login/Login';
import MyProfile from '../pages/Profile/MyProfile';
import MyGallery from '../pages/Profile/MyGallery';
import MyJobOffers from '../pages/MyJobOffers/MyJobOffers';
import Portfolio from '../pages/Profile/Portfolio';
import ExplorePage from '../pages/Explore/ExplorePage';
import JobOffersPage from '../pages/JobOffers/JobOffersPage';

const Routes = ({ storeUser, loggedUser, setAlert }) => {
	// const notLoggedStr = 'You need to log in';

	return (
		<main>
			<Switch>
				<Route path="/" exact render={() => <HomePage loggedUser={loggedUser} setAlert={setAlert} />} />
				<Route path="/signup" render={props => <Signup {...props} storeUser={storeUser} setAlert={setAlert} />} />
				<Route path="/login" render={props => <Login {...props} storeUser={storeUser} setAlert={setAlert} />} />
				<Route
					path="/my-profile"
					render={() =>
						loggedUser ? (
							<MyProfile loggedUser={loggedUser} storeUser={storeUser} setAlert={setAlert} />
						) : (
							<Redirect to="/" />
						)
					}
				/>

				{/* Not directly used route */}
				<Route
					path="/my-portfolio"
					render={() =>
						loggedUser && loggedUser.role === 'ARTIST' ? (
							<Portfolio loggedUser={loggedUser} storeUser={storeUser} self={true} setAlert={setAlert} />
						) : (
							<Redirect to="/" />
						)
					}
				/>

				<Route
					path="/my-gallery"
					render={() =>
						loggedUser && loggedUser.role === 'ARTIST' ? (
							<MyGallery loggedUser={loggedUser} setAlert={setAlert} />
						) : (
							<Redirect to="/" />
						)
					}
				/>

				<Route
					path="/my-job-offers"
					render={() =>
						loggedUser ? <MyJobOffers loggedUser={loggedUser} setAlert={setAlert} /> : <Redirect to="/" />
					}
				/>

				<Route
					path="/portfolio/:artist_id"
					render={props =>
						loggedUser ? (
							<Portfolio
								loggedUser={loggedUser}
								storeUser={storeUser}
								self={false}
								artist_id={props.match.params.artist_id}
								setAlert={setAlert}
							/>
						) : (
							<Redirect to="/" />
						)
					}
				/>

				<Route
					path="/explore"
					render={() =>
						loggedUser ? <ExplorePage loggedUser={loggedUser} setAlert={setAlert} /> : <Redirect to="/" />
					}
				/>

				<Route
					path="/job-offers"
					render={() =>
						loggedUser ? <JobOffersPage loggedUser={loggedUser} setAlert={setAlert} /> : <Redirect to="/" />
					}
				/>
			</Switch>
		</main>
	);
};

export default Routes;
