import { Col, Image } from 'react-bootstrap';
import './PortfolioImageItem.css';

const PortfolioImageItem = ({ id, img_url, openDetails, limit }) => {
	return (
		<Col sm={limit ? 6 : 12} md={limit ? 4 : 6} lg={4} xl={!limit && 3}>
			<button className="portfolio-item" onClick={() => openDetails(id)}>
				<div className="content">
					<Image src={img_url} fluid />
				</div>
			</button>
		</Col>
	);
};

export default PortfolioImageItem;
