import { Component } from 'react';
import { Button, Col, Container, Form, Image, Modal, Row } from 'react-bootstrap';
import { Link } from 'react-router-dom';
import PortfolioService from '../../../services/portfolio.service';
import './PortfolioImageDetails.css';

class PortfolioImageDetails extends Component {
	constructor() {
		super();

		this.state = {
			portfolioImage: undefined,
			liked: false,
			tagInput: false,
			showDelete: false,
			newTags: '',
		};

		this.portfolioService = new PortfolioService();
	}

	componentDidMount = () => {
		this.portfolioService
			.getImage(this.props.image_id)
			.then(response => {
				const liked = this.props.loggedUser && response.data.liked.includes(String(this.props.loggedUser._id));
				this.setState({ portfolioImage: response.data, liked });
			})
			.catch(err => this.props.setAlert(err.response.data.message));
	};

	updateLikes = () => {
		this.portfolioService
			.likeImage(this.state.portfolioImage._id, this.state.liked)
			.then(response => {
				const liked = this.props.loggedUser && response.data.liked.includes(String(this.props.loggedUser._id));
				this.setState({
					portfolioImage: {
						...this.state.portfolioImage,
						liked: response.data.liked,
						likes: response.data.likes,
					},

					liked,
				});
			})
			.catch(err => this.props.setAlert(err.response.data.message));
	};

	deleteImage = () => {
		this.portfolioService
			.deleteImage(this.state.portfolioImage._id)
			.then(() => {
				this.setState({
					portfolioImage: undefined,
				});
				this.props.refreshList();
				this.props.closeModal();
			})
			.catch(err => this.props.setAlert(err.response.data.message));
	};

	deleteTag = index => {
		const tags = [...this.state.portfolioImage.tags];
		tags.splice(index, 1);

		this.portfolioService
			.updateImage(this.state.portfolioImage._id, { img_url: this.state.portfolioImage.img_url, tags })
			.then(response => this.setState({ portfolioImage: response.data }))
			.catch(err => this.props.setAlert(err.response.data.message));
	};

	handleInputChange = e => {
		this.setState({ newTags: e.target.value });
	};

	handleTagsSubmit = e => {
		e.preventDefault();

		const tags = this.state.portfolioImage.tags.concat(this.state.newTags.split(/,\s*/));

		this.portfolioService
			.updateImage(this.state.portfolioImage._id, {
				img_url: this.state.portfolioImage.img_url,
				tags,
			})
			.then(response =>
				this.setState({
					portfolioImage: response.data,
					tagInput: false,
					newTags: '',
				})
			)
			.catch(err => this.props.setAlert(err.response.data.message));
	};

	render = () => (
		<>
			<Modal.Header>
				{this.state.portfolioImage && (
					<Container className="portfolio-details">
						<Row className="justify-content-between align-items-center">
							<Col>
								<h2>
									<span style={{ fontWeight: 100, fontStyle: 'oblique', fontSize: '0.8em' }}>Artist: </span>
									<Link
										to={
											this.state.portfolioImage.artist_id._id === this.props.loggedUser?._id
												? `my-portfolio`
												: `/portfolio/${this.state.portfolioImage.artist_id._id}`
										}
									>
										{this.state.portfolioImage.artist_id.portfolio.name}{' '}
										{this.state.portfolioImage.artist_id.portfolio.last_name}
									</Link>
								</h2>

								<div className="tags">
									<label>Tags:</label>
									{this.state.portfolioImage.tags.map((tag, i) => (
										<span key={i} className="tag-item">
											{tag}
											{this.state.portfolioImage.artist_id._id === this.props.loggedUser?._id && (
												<Button className="delete-tag-btn" onClick={() => this.deleteTag(i)}>
													<span className="icon-plus small-icon"></span>
												</Button>
											)}
										</span>
									))}

									{this.state.portfolioImage.artist_id._id === this.props.loggedUser?._id && (
										<>
											<span
												as={Button}
												style={{
													transform: this.state.tagInput && 'rotate(45deg) scale(1.5)',
													backgroundColor: this.state.tagInput && 'transparent',
													borderRadius: this.state.tagInput && '50%',
												}}
												className="add-tag-btn tag-item icon-plus small-icon"
												onClick={() => this.setState({ tagInput: !this.state.tagInput })}
											></span>

											<Form
												onSubmit={this.handleTagsSubmit}
												hidden={!this.state.tagInput}
												className="add-tags-form"
											>
												<Form.Group controlId="newTags">
													<Form.Label>New tags (comma separated)</Form.Label>
													<Form.Control
														type="textarea"
														value={this.state.newTags}
														onChange={this.handleInputChange}
														name="newTags"
														placeholder="First, second, third..."
													/>
												</Form.Group>

												<Button style={{ marginTop: '20px', width: '100%' }} variant="dark" type="submit">
													Add tags
												</Button>
											</Form>
										</>
									)}
								</div>

								<p className="likes">
									<label>Likes:</label>
									<span>{this.state.portfolioImage.likes}</span>
								</p>
							</Col>

							{this.props.loggedUser && (
								<Col xs={2} className="like-btn-col">
									<Button variant="transparent" onClick={this.updateLikes}>
										{this.state.liked ? (
											<span className="icon-heart"></span>
										) : (
											<span className="icon-heart-empty"></span>
										)}
									</Button>
								</Col>
							)}

							{this.state.portfolioImage.artist_id._id === this.props.loggedUser?._id && (
								<Col xs={2} className="delete-btn-col">
									<Button variant="warning" className="delete-btn" onClick={this.deleteImage}>
										<span className="icon-trash-empty">{/* Delete */}</span>
									</Button>
								</Col>
							)}
						</Row>
					</Container>
				)}
			</Modal.Header>
			<Modal.Body className="full-width no-padding">
				<Container fluid className="portfolio-details no-padding">
					<Row>
						<Col xs={12}>
							{this.state.portfolioImage ? (
								<>
									<Image src={this.state.portfolioImage.img_url} />
								</>
							) : (
								<>
									<span>Loading...</span>
								</>
							)}
						</Col>
					</Row>
				</Container>
			</Modal.Body>
		</>
	);
}

export default PortfolioImageDetails;
