import { Component } from 'react';
import { Form, Button, Container } from 'react-bootstrap';
import JobOffersService from '../../../services/jobOffer.service';

class NewJobOfferForm extends Component {
	constructor() {
		super();

		this.state = {
			brand: '',
			title: '',
			description: '',
			tags: '',
		};

		this.jobOffersService = new JobOffersService();
	}

	handleInputChange = e => {
		let { name, value } = e.target;
		this.setState({ [name]: value });
	};

	handleFormSubmit = e => {
		e.preventDefault();

		this.jobOffersService
			.saveJobOffer({ ...this.state, tags: this.state.tags.split(/,\s*/) })
			.then(response => {
				this.props.refreshList();
				this.props.closeModal();
			})
			.catch(err => this.props.setAlert(err.response.data.message));
	};

	render = () => (
		<Container>
			<Form onSubmit={this.handleFormSubmit}>
				<Form.Group controlId="brand">
					<Form.Label>Brand</Form.Label>
					<Form.Control type="text" value={this.state.brand} onChange={this.handleInputChange} name="brand" />
				</Form.Group>

				<br />

				<Form.Group controlId="title">
					<Form.Label>Title</Form.Label>
					<Form.Control type="text" value={this.state.title} onChange={this.handleInputChange} name="title" />
				</Form.Group>

				<br />

				<Form.Group controlId="description">
					<Form.Label>Description</Form.Label>
					<Form.Control
						type="textarea"
						value={this.state.description}
						onChange={this.handleInputChange}
						name="description"
					/>
				</Form.Group>

				<br />

				<Form.Group controlId="tags">
					<Form.Label>Tags (comma separated)</Form.Label>
					<Form.Control
						type="textarea"
						value={this.state.tags}
						onChange={this.handleInputChange}
						name="tags"
						placeholder="First, second, third..."
					/>
				</Form.Group>

				<Button style={{ marginTop: '20px', width: '100%' }} variant="dark" type="submit">
					Add job offer
				</Button>
			</Form>
		</Container>
	);
}

export default NewJobOfferForm;
